import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  // Calculate plane dimensions from atlas source rect aspect ratio (512 / 320 = 1.6)
  const aspectRatio = 512 / 320;
  const height = 1;
  const width = height * aspectRatio;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(width, height);

  // Load texture
  const tex = ctx.textureLoader.load(config.assets.imageUrl);
  tex.colorSpace = THREE.SRGBColorSpace;

  // Create material using TSL
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: texture(tex),
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement
  mesh.position.fromArray(config.scenePosition);
  mesh.rotation.set(config.sceneRotation[0], config.sceneRotation[1], config.sceneRotation[2]);
  mesh.scale.fromArray(config.sceneScale);

  // Setup cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    tex.dispose();
  };

  // Setup handlers
  mesh.userData.handlers = {};

  return mesh;
}
